INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM208QTZR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A community center offers two programs: ceramics and woodworking. Of the $97$ members, $41$ are enrolled in ceramics and $56$ are enrolled in woodworking. Among the ceramics participants, $23$ have previously taken an art class, and among the woodworking participants, $19$ have previously taken an art class. If a member is selected at random from those who have previously taken an art class, what is the probability that the member is enrolled in ceramics?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{97}$"},{"key":"B","text":"$\\frac{23}{41}$"},{"key":"C","text":"$\\frac{23}{42}$"},{"key":"D","text":"$\\frac{19}{42}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The condition restricts the sample space to members who have previously taken an art class: $23 + 19 = 42$ total members with prior art experience. Of these, $23$ are enrolled in ceramics, so the conditional probability is $\\frac{23}{42}$. The distractor $\\frac{23}{97}$ uses the entire membership as the denominator, computing the unconditional probability rather than the conditional probability given prior art class experience. The distractor $\\frac{23}{41}$ uses the total number of ceramics participants as the denominator instead of the total number of members with prior art experience, confusing the conditioning event. The distractor $\\frac{19}{42}$ correctly identifies the art-experience total but uses the number of woodworking participants with art experience in the numerator, answering for the wrong program.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20YQE1V', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 2(x + 3)^2 - 5$. The graph of $y = f(x - 4)$ has a vertex at which of the following points?', NULL, $lyceon_json$[{"key":"A","text":"$(1, -5)$"},{"key":"B","text":"$(-7, -5)$"},{"key":"C","text":"$(-3, -9)$"},{"key":"D","text":"$(1, -9)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex of $f(x) = 2(x + 3)^2 - 5$ is at $(-3, -5)$. Replacing $x$ with $x - 4$ in $f$ shifts the graph $4$ units to the right: $f(x - 4) = 2((x - 4) + 3)^2 - 5 = 2(x - 1)^2 - 5$, so the new vertex is $(1, -5)$. The distractor $(-7, -5)$ shifts the vertex $4$ units to the left instead of to the right, adding $-4$ to the $x$-coordinate. The distractor $(-3, -9)$ subtracts $4$ from the $y$-coordinate instead of shifting horizontally, confusing horizontal and vertical transformations. The distractor $(1, -9)$ correctly shifts the $x$-coordinate right by $4$ but also incorrectly subtracts $4$ from the $y$-coordinate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM223EFJC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h(x) = -(x - 7)^2 + 13$ has a maximum value. What is this maximum value?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'D', NULL, E'The function $h(x) = -(x - 7)^2 + 13$ is in vertex form $a(x - h)^2 + k$ with $a = -1 < 0$, so the parabola opens downward and the vertex $(7, 13)$ is the maximum point. The maximum value of $h(x)$ is $13$. The distractor $-13$ negates the maximum value, applying a sign error to the constant $k$. The distractor $-7$ confuses the $x$-coordinate of the vertex with the maximum output value and negates it. The distractor $7$ identifies the $x$-coordinate of the vertex rather than the $y$-coordinate, which represents the maximum value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23LY086', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $t$ satisfies the inequality $7t + 13 > 62$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting 13 from both sides gives $7t > 49$, and dividing both sides by 7 gives $t > 7$. Among the choices, only $11$ is strictly greater than 7, since $7(11) + 13 = 90 > 62$. The value $4$ gives $7(4) + 13 = 41$, which does not exceed 62, reflecting a concept gap about the direction of the inequality. The value $6$ gives $7(6) + 13 = 55$, which is still less than 62, possibly from an arithmetic slip such as computing $62 - 13 = 49$ but then dividing by an incorrect number. The value $7$ gives $7(7) + 13 = 62$, which equals 62 but is not strictly greater, reflecting confusion between $>$ and $\\geq$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23QF6JJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A physical therapy practice randomly assigns $90$ patients recovering from knee surgery to two groups. One group follows a new stretching protocol, and the other group follows the existing standard protocol. After $10$ weeks, patients in the new protocol group have significantly greater range of motion on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new stretching protocol is effective for all patients recovering from any type of surgery."},{"key":"B","text":"Patients who chose the new protocol were more motivated to recover."},{"key":"C","text":"The new stretching protocol likely caused the improvement in range of motion among the patients in this experiment."},{"key":"D","text":"There is an association between the new protocol and greater range of motion, but causation cannot be established."}]$lyceon_json$::jsonb, 'C', NULL, E'Because patients were randomly assigned to groups, this is a randomized experiment. Random assignment controls for confounding variables such as age, fitness level, or surgical severity, so a causal conclusion about the new protocol''s effect is appropriate for the study population. The claim about all patients recovering from any type of surgery overgeneralizes beyond this study''s population of knee surgery patients at one practice. The claim about patients choosing the protocol contradicts the study design — random assignment means patients did not select their protocol, so self-selection bias does not apply. The claim that causation cannot be established applies to observational studies, not to properly randomized experiments where causal inference is the primary purpose of the design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23WHDBK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A coach records the following race times, in seconds, for 8 sprinters: $38, 44, 51, 56, 62, 68, 73, 84$. If the time of 84 seconds is removed from the data set, which of the following correctly describes the change in the mean and the range?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the range decrease."},{"key":"B","text":"The mean decreases and the range stays the same."},{"key":"C","text":"The mean stays the same and the range decreases."},{"key":"D","text":"The mean increases and the range decreases."}]$lyceon_json$::jsonb, 'A', NULL, E'The original 8 times sum to $38 + 44 + 51 + 56 + 62 + 68 + 73 + 84 = 476$. Original mean: $\\frac{476}{8} = 59.5$. Original range: $84 - 38 = 46$. After removing 84, the 7 remaining times sum to 392. New mean: $\\frac{392}{7} = 56$, which is lower. New range: $73 - 38 = 35$, which is also lower. So both the mean and the range decrease. The claim that the range stays the same is wrong because the maximum value was removed, reducing the range from 46 to 35. The claim that the mean stays the same ignores that the removed value (84) is well above the original mean (59.5), pulling the mean down. The claim that the mean increases contradicts the fact that a value above the mean was removed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26MPUDZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $BC$ such that $AD$ bisects angle $A$. If the measure of angle $B$ is $47^\\circ$ and the measure of angle $ADB$ is $109^\\circ$, what is the measure, in degrees, of angle $C$?', NULL, $lyceon_json$[{"key":"A","text":"$24^\\circ$"},{"key":"B","text":"$48^\\circ$"},{"key":"C","text":"$71^\\circ$"},{"key":"D","text":"$85^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'In triangle $ABD$, the angles sum to $180^\\circ$: angle $BAD + 47^\\circ + 109^\\circ = 180^\\circ$, so angle $BAD = 24^\\circ$. Since $AD$ bisects angle $A$, angle $DAC = 24^\\circ$ as well, making angle $A = 48^\\circ$. In triangle $ABC$: $48^\\circ + 47^\\circ + \\text{angle } C = 180^\\circ$, giving angle $C = 85^\\circ$. Alternatively, in triangle $ADC$: angle $ADC = 180^\\circ - 109^\\circ = 71^\\circ$, so $24^\\circ + \\text{angle } C + 71^\\circ = 180^\\circ$, confirming angle $C = 85^\\circ$. The value $24^\\circ$ is only the half-angle $BAD$, stopping too early in the reasoning. The value $48^\\circ$ is the full angle $A$, answering the wrong angle. The value $71^\\circ$ is the supplement of angle $ADB$ (i.e., angle $ADC$), misidentifying which angle was asked for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26PW6HV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(-1, 13)$ and $(3, -7)$. What is the slope of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'The slope is $m = \\frac{-7 - 13}{3 - (-1)} = \\frac{-20}{4} = -5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
