INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27AT89S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling firm surveys a random sample of $750$ registered voters in a state and finds that $47\\%$ support Candidate X while $53\\%$ support Candidate Y, each with a margin of error of $2.8\\%$. A campaign spokesperson states: "Candidate Y holds an insurmountable lead among voters in this state." Which of the following best evaluates the spokesperson''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $53\\%$ exceeds $47\\%$ by $6$ percentage points."},{"key":"B","text":"The claim is justified because a sample of $750$ voters is large enough to eliminate sampling error."},{"key":"C","text":"The claim is not justified because the confidence intervals for support of Candidate X ($44.2\\%$ to $49.8\\%$) and Candidate Y ($50.2\\%$ to $55.8\\%$) overlap, so the lead is within sampling variability."},{"key":"D","text":"The claim is not justified because the confidence intervals do not overlap, but the word \"insurmountable\" overstates the certainty that can be drawn from a single poll with a $2.8\\%$ margin of error."}]$lyceon_json$::jsonb, 'D', NULL, E'The confidence interval for Candidate X is $44.2\\%$ to $49.8\\%$, and for Candidate Y is $50.2\\%$ to $55.8\\%$. These intervals do not overlap, so the data support a conclusion that Candidate Y is ahead. However, the word "insurmountable" overstates what a single poll can establish — opinions can shift, and the margin of error still reflects meaningful uncertainty about the exact size of the lead. The claim based solely on $53\\% > 47\\%$ uses partial reasoning by ignoring the margin of error entirely. The assertion that $750$ voters eliminate sampling error reflects a fundamental misunderstanding — no finite sample eliminates sampling variability. The claim that the intervals overlap is factually incorrect: $49.8\\%$ (upper bound for Candidate X) is less than $50.2\\%$ (lower bound for Candidate Y), so the intervals are disjoint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27Y8MID', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A nonprofit organization surveys a random sample of $200$ donors and finds that $58\\%$ support expanding the scholarship program. A second survey of a random sample of $800$ donors at the same organization finds that $61\\%$ support expanding the program, with a smaller margin of error. Which of the following best explains why the second survey has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second survey found a higher support rate, which decreases the margin of error."},{"key":"B","text":"The second survey was conducted with more experienced interviewers, which reduced bias."},{"key":"C","text":"The second survey sampled four times as many donors, which decreases the margin of error."},{"key":"D","text":"The second survey used a different question format that was easier to understand."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error is inversely related to the square root of the sample size. The second survey sampled $800$ donors compared to $200$, a fourfold increase, so its margin of error is approximately halved. The claim that a higher support rate decreases the margin of error conflates the value of the statistic with sampling precision — while the proportion does have a minor effect on margin of error, the dominant factor here is the much larger sample size. The suggestion about more experienced interviewers introduces an irrelevant factor unrelated to the statistical definition of margin of error. The claim about a different question format is unsubstantiated and does not address how margin of error is calculated from sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28OSUIG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 + 10x - 18y + 42 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{42}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{68}$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 + 10x + 25) + (y^2 - 18y + 81) = -42 + 25 + 81$, which gives $(x + 5)^2 + (y - 9)^2 = 64$. The radius is $r = \\sqrt{64} = 8$. The value $\\sqrt{42}$ comes from taking the square root of the constant term $42$ from the original equation without completing the square, misreading the equation structure. The value $\\sqrt{68}$ arises from an arithmetic slip in the completing-the-square computation, such as computing $-42 + 25 + 81 = 68$ by miscombining the first two terms as $-42 + 25 = -17$ and then $-17 + 81 = 64$... actually getting $68$ from adding $-42 + 25 = -17$ then incorrectly computing $-17 + 81 = 68$ instead of $64$, then forgetting to take the square root. The value $64$ reports $r^2$ instead of $r$, a concept gap about extracting the radius from standard form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM298UHHA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A rectangular prism has dimensions $14$ cm $\\times$ $9$ cm $\\times$ $22$ cm. A cylindrical hole with diameter $6$ cm is drilled through the entire $22$-cm length of the prism. What is the volume, in cubic centimeters, of the remaining solid?', NULL, $lyceon_json$[{"key":"A","text":"$2772 - 198\\pi$"},{"key":"B","text":"$2772 - 792\\pi$"},{"key":"C","text":"$2574$"},{"key":"D","text":"$2772 - 396\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of the rectangular prism is $14 \\times 9 \\times 22 = 2772$ cubic centimeters. The cylindrical hole has diameter $6$ cm, so its radius is $3$ cm. The cylinder''s volume is $\\pi r^2 h = \\pi(3)^2(22) = 198\\pi$ cubic centimeters. The remaining solid has volume $2772 - 198\\pi$. The expression $2772 - 792\\pi$ uses the diameter $6$ as the radius, computing $\\pi(6)^2(22) = 792\\pi$, an equation setup error confusing radius and diameter. The value $2574$ subtracts $198$ without the factor of $\\pi$ ($2772 - 198 = 2574$), a concept gap about the cylinder volume formula requiring $\\pi$. The expression $2772 - 396\\pi$ doubles the correct cylinder volume ($2 \\times 198\\pi = 396\\pi$), an arithmetic slip from an erroneous extra factor of $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29C3X6F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A drawer contains $11$ striped socks and $7$ solid-colored socks. Two socks are drawn one at a time without replacement. Given that the first sock drawn is solid-colored, what is the probability that the second sock drawn is also solid-colored?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{18}$"},{"key":"B","text":"$\\frac{6}{17}$"},{"key":"C","text":"$\\frac{7}{17}$"},{"key":"D","text":"$\\frac{6}{18}$"}]$lyceon_json$::jsonb, 'B', NULL, E'After one solid-colored sock is drawn, $17$ socks remain: $11$ striped and $6$ solid-colored. The conditional probability that the second sock is also solid-colored is $\\frac{6}{17}$. The distractor $\\frac{7}{18}$ uses the original counts ($7$ solid out of $18$ total), failing to account for the without-replacement condition. The distractor $\\frac{7}{17}$ correctly reduces the total to $17$ but keeps the solid count at $7$, failing to remove the drawn solid sock from the numerator. The distractor $\\frac{6}{18}$ reduces the solid count to $6$ but keeps the total at $18$, an error in applying the without-replacement adjustment to only one part of the fraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AE8CSH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $GHK$, the measure of angle $G$ is $43^\\circ$ and the measure of angle $H$ is $78^\\circ$. What is the measure, in degrees, of angle $K$?', NULL, $lyceon_json$[{"key":"A","text":"$35^\\circ$"},{"key":"B","text":"$59^\\circ$"},{"key":"C","text":"$102^\\circ$"},{"key":"D","text":"$121^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. So angle $K = 180^\\circ - 43^\\circ - 78^\\circ = 59^\\circ$. The value $35^\\circ$ comes from subtracting the two given angles from each other ($78 - 43 = 35$) instead of subtracting their sum from $180$. The value $102^\\circ$ is the result of subtracting only one angle from $180^\\circ$ ($180 - 78 = 102$), stopping before subtracting the second. The value $121^\\circ$ results from adding the two given angles ($43 + 78 = 121$) and treating the sum as the missing angle instead of subtracting from $180$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BE8LBZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A veterinary clinic observes that cat owners who purchase premium food brands tend to bring their cats in for fewer sick visits per year than cat owners who purchase standard food brands. Food brand selection is entirely the owner''s choice. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Purchasing premium cat food causes fewer sick visits."},{"key":"B","text":"There is an association between purchasing premium cat food and fewer sick visits."},{"key":"C","text":"The clinic should recommend that all cat owners switch to premium food brands."},{"key":"D","text":"Standard food brands are nutritionally inferior to premium food brands."}]$lyceon_json$::jsonb, 'B', NULL, E'Because food brand selection is voluntary, this is an observational study. Owners who purchase premium brands may differ from other owners in ways that also affect pet health — for example, they may have higher incomes, provide more preventive care, or be more attentive to pet wellness in general. The data establish an association but cannot determine causation. The causal claim that premium food causes fewer sick visits is unwarranted without random assignment. The recommendation to switch all owners to premium food is a policy prescription that goes beyond what observational data can support. The claim that standard brands are nutritionally inferior draws a product-quality conclusion that the study design does not test.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BOXDHF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store decreases the price of a jacket by $25\\%$. One month later, the store increases the reduced price by $25\\%$. If the original price of the jacket was $\\$240$, what is the final price after both changes?', NULL, $lyceon_json$[{"key":"A","text":"$\\$180$"},{"key":"B","text":"$\\$210$"},{"key":"C","text":"$\\$225$"},{"key":"D","text":"$\\$240$"}]$lyceon_json$::jsonb, 'C', NULL, E'After a $25\\%$ decrease, the price becomes $240 \\times 0.75 = \\$180$. After a $25\\%$ increase on $\\$180$, the price becomes $180 \\times 1.25 = \\$225$. The value $\\$180$ results from computing only the first decrease and stopping, ignoring the subsequent increase. The value $\\$210$ results from an arithmetic slip, such as computing $25\\%$ of $\\$120$ instead of $25\\%$ of $\\$180$ when applying the increase. The value $\\$240$ comes from the misconception that a $25\\%$ decrease followed by a $25\\%$ increase returns to the original price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C9BSX7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of length $13$ inches and $27$ inches and a height of $8$ inches. What is the area of the trapezoid, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$104$"},{"key":"B","text":"$160$"},{"key":"C","text":"$216$"},{"key":"D","text":"$320$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2)h = \\frac{1}{2}(13 + 27)(8) = \\frac{1}{2}(40)(8) = 160$ square inches. The value $104$ results from multiplying only the shorter base by the height ($13 \\times 8 = 104$), ignoring the longer base and the averaging factor. The value $216$ comes from multiplying the longer base by the height ($27 \\times 8 = 216$), ignoring the shorter base and the factor of $\\frac{1}{2}$. The value $320$ results from computing $(13 + 27) \\times 8 = 320$ but omitting the required factor of $\\frac{1}{2}$ in the trapezoid formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CHS8VQ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bakery sells loaves of sourdough bread for $s$ dollars each and bags of dinner rolls for $r$ dollars each. If 7 loaves of sourdough and 3 bags of dinner rolls cost $\\$83$, and 4 loaves of sourdough and 3 bags of dinner rolls cost $\\$56$, what is the cost, in dollars, of one loaf of sourdough?', NULL, $lyceon_json$[{"key":"A","text":"$\\$5$"},{"key":"B","text":"$\\$7$"},{"key":"C","text":"$\\$9$"},{"key":"D","text":"$\\$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'The system is $7s + 3r = 83$ and $4s + 3r = 56$. Subtracting the second from the first eliminates $r$: $3s = 27$, so $s = 9$. One loaf of sourdough costs $\\$9$. Substituting back gives $63 + 3r = 83$, so $3r = 20$ and $r = 20/3 \\approx 6.67$. The distractor $\\$5$ could result from misreading the question and confusing the variables, solving for a different quantity. The distractor $\\$7$ comes from an arithmetic slip such as computing $83 - 56 = 27$ but then dividing by 4 instead of 3. The distractor $\\$18$ comes from stopping at $3s = 27$ and mistakenly doubling the result instead of dividing by 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E71X6C', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x + 11y = 77$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 7)$"},{"key":"B","text":"$(\\frac{77}{3}, 0)$"},{"key":"C","text":"$(0, -7)$"},{"key":"D","text":"$(0, 11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting gives $11y = 77$, so $y = 7$, and the intercept is $(0, 7)$. The point $(\\frac{77}{3}, 0)$ is the $x$-intercept, indicating the question was misread as asking for the $x$-intercept. The point $(0, -7)$ comes from a sign error, incorrectly attaching a negative sign when dividing $77$ by $11$. The point $(0, 11)$ reflects a concept gap, confusing the coefficient of $y$ with the intercept value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EDJEEK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $4(3x + 2) = 7x - 12$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -4$"},{"key":"B","text":"$x = -2$"},{"key":"C","text":"$x = 4$"},{"key":"D","text":"$x = -\\frac{4}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $12x + 8 = 7x - 12$. Subtracting $7x$ from both sides: $5x + 8 = -12$. Subtracting $8$ from both sides: $5x = -20$. Dividing by $5$: $x = -4$. The distractor $x = -2$ results from an arithmetic slip — computing $-12 - 8$ as $-10$ instead of $-20$, giving $5x = -10$ and $x = -2$. The distractor $x = 4$ comes from a sign error — dropping the negative when dividing $-20$ by $5$, yielding $4$ instead of $-4$. The distractor $x = -\\frac{4}{5}$ results from an equation setup error — after reaching $5x + 8 = -12$, adding $8$ to $-12$ instead of subtracting, computing $5x = -12 + 8 = -4$ and then $x = -\\frac{4}{5}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FET6U3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following points $(x, y)$ lies in the solution region of both $4x - 3y \\geq 19$ and $2x + 9y < 31$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 2)$"},{"key":"B","text":"$(5, 3)$"},{"key":"C","text":"$(8, 1)$"},{"key":"D","text":"$(7, 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(8, 1)$: the first inequality gives $4(8) - 3(1) = 32 - 3 = 29 \\geq 19$, which is true, and the second gives $2(8) + 9(1) = 16 + 9 = 25 < 31$, which is also true. The point $(3, 2)$ fails the first inequality because $4(3) - 3(2) = 12 - 6 = 6$, which is not greater than or equal to 19, reflecting a concept gap about evaluating linear expressions that yield small values. The point $(5, 3)$ fails the first inequality because $4(5) - 3(3) = 20 - 9 = 11$, which does not reach 19, likely resulting from a sign or magnitude error when estimating the boundary. The point $(7, 2)$ satisfies the first inequality ($4(7) - 3(2) = 28 - 6 = 22 \\geq 19$, true) but fails the second ($2(7) + 9(2) = 14 + 18 = 32 < 31$ is false), reflecting a failure to check both constraints.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FM7LLW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A tablet originally priced at $\\$170$ is on sale for $35\\%$ off. What is the sale price, in dollars, of the tablet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '110.5', ARRAY['221/2', '110.5'], E'The discount is $0.35 \\times 170 = \\$59.50$. The sale price is $170 - 59.50 = \\$110.50$. A common error is reporting only the discount amount of $\\$59.50$ rather than subtracting it from the original price. Another error is subtracting 35 from 170 to get $\\$135$, treating the percentage as a dollar amount.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2S1YZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{6x^2 + 19x - 77}{3x - 7} = ax + b$ for all $x \\neq \\frac{7}{3}$, what is the value of $a - b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-9', ARRAY['-9'], E'Factor the numerator $6x^2 + 19x - 77$. We seek two numbers with product $6 \\times (-77) = -462$ and sum $19$. Those numbers are $33$ and $-14$. Rewriting: $6x^2 + 33x - 14x - 77 = 3x(2x + 11) - 7(2x + 11) = (3x - 7)(2x + 11)$. Dividing by $(3x - 7)$ gives $2x + 11$, so $a = 2$ and $b = 11$. Therefore $a - b = 2 - 11 = -9$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HIB5EW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One pair of alternate interior angles has measures $(5x + 11)^\\circ$ and $(8x - 19)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$10$"},{"key":"C","text":"$13$"},{"key":"D","text":"$61$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so $5x + 11 = 8x - 19$. Solving: $11 + 19 = 8x - 5x$, giving $30 = 3x$ and $x = 10$. Verification: $5(10) + 11 = 61^\\circ$ and $8(10) - 19 = 61^\\circ$. The value $7$ results from an arithmetic slip such as computing $30 / 3$ incorrectly or mishandling the sign when moving terms. The value $13$ comes from treating the angles as supplementary instead of equal, setting $5x + 11 + 8x - 19 = 180$, yielding $13x - 8 = 180$, so $13x = 188$ and $x \\approx 14.5$, then rounding or miscalculating to get $13$, reflecting a concept gap about the alternate interior angle relationship. The value $61$ is the angle measure itself ($5(10) + 11 = 61$), not the value of $x$, reflecting partial reasoning that computes an intermediate result but reports the wrong quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JKTAG6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $13x - 29 = 62$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Adding $29$ to both sides gives $13x = 91$. Dividing both sides by $13$ yields $x = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JTM9P7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the $xy$-plane, a circle has equation $(x - 4)^2 + (y + 1)^2 = 169$. The line $y = 4$ intersects the circle at two points. What is the distance between these two points?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$12$"},{"key":"C","text":"$13$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'D', NULL, E'The circle has center $(4, -1)$ and radius $\\sqrt{169} = 13$. The perpendicular distance from the center to the line $y = 4$ is $|4 - (-1)| = 5$. A line from the center perpendicular to the chord bisects the chord, forming a right triangle with hypotenuse equal to the radius and one leg equal to the perpendicular distance. The half-chord length is $\\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. The full chord length (distance between the two intersection points) is $2 \\times 12 = 24$. The value $5$ is the perpendicular distance from the center to the line, not the chord length. The value $12$ is only the half-chord length, stopping before doubling. The value $13$ is the radius of the circle, not the chord length.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L05FTC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a school election, $36\\%$ of voters chose candidate $P$ and $28\\%$ chose candidate $Q$. The remaining voters were split equally among four other candidates. If candidate $P$ received 252 votes, how many votes did each of the four other candidates receive?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$63$"},{"key":"C","text":"$196$"},{"key":"D","text":"$252$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since candidate $P$ received $36\\%$ of the votes and got 252 votes, the total number of voters is $252 \\div 0.36 = 700$. The remaining percentage is $100\\% - 36\\% - 28\\% = 36\\%$, so $0.36 \\times 700 = 252$ votes were split equally among four candidates, giving each $252 \\div 4 = 63$ votes. The value 49 results from using candidate $Q$''s $28\\%$ as the remaining percentage instead of computing it correctly, yielding $0.28 \\times 700 \\div 4 = 49$. The value 196 is the number of votes candidate $Q$ received ($0.28 \\times 700 = 196$), not one of the four other candidates. The value 252 is the total remaining votes before dividing by 4, reflecting a failure to complete the final division step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3729T', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $5x^2 - 23x + 12 = 0$, what is the smaller value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/5', ARRAY['3/5', '0.6', '.6'], E'Using the quadratic formula: $x = \\frac{23 \\pm \\sqrt{(-23)^2 - 4(5)(12)}}{2(5)} = \\frac{23 \\pm \\sqrt{529 - 240}}{10} = \\frac{23 \\pm \\sqrt{289}}{10} = \\frac{23 \\pm 17}{10}$. This gives $x = \\frac{40}{10} = 4$ or $x = \\frac{6}{10} = \\frac{3}{5}$. The smaller value is $\\frac{3}{5}$. This can be verified by factoring: $5x^2 - 23x + 12 = (5x - 3)(x - 4) = 0$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LNV52L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The seven values in a data set are $11, 17, 23, 29, 34, 41$, and $k$, where $k$ is a positive integer. If the mean of the data set is 25, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'The mean of the seven values is $\\frac{11 + 17 + 23 + 29 + 34 + 41 + k}{7} = 25$. The sum of the known values is $11 + 17 + 23 + 29 + 34 + 41 = 155$. So $\\frac{155 + k}{7} = 25$, giving $155 + k = 175$, and $k = 20$. A common error is dividing by 6 instead of 7, forgetting to include $k$ in the count, which yields $k = -5$. Another error is summing the known values incorrectly.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LPUDCE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'An electrician charges a $\\$47$ inspection fee plus $\\$29$ per hour of labor. Which function $f(h)$ gives the total cost, in dollars, after $h$ hours of labor?', NULL, $lyceon_json$[{"key":"A","text":"$f(h) = 29h + 47$"},{"key":"B","text":"$f(h) = 47h + 29$"},{"key":"C","text":"$f(h) = 76h$"},{"key":"D","text":"$f(h) = 29h - 47$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the fixed inspection fee plus the hourly rate times the number of hours: $f(h) = 29h + 47$. The function $f(h) = 47h + 29$ reflects a concept gap, swapping the roles of the one-time fee and the hourly rate. The function $f(h) = 76h$ comes from an equation setup error, adding $29$ and $47$ into a single rate and treating the total as purely proportional to hours. The function $f(h) = 29h - 47$ arises from a sign error, subtracting the inspection fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LSM4IL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours of sunlight per day and a plant''s weekly height growth in centimeters. The line of best fit has a slope of 2.7. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight per day, the predicted weekly growth increases by 2.7 centimeters."},{"key":"B","text":"A plant that receives 2.7 hours of sunlight per day will reach its maximum height."},{"key":"C","text":"The weekly growth is always 2.7 times the number of hours of sunlight."},{"key":"D","text":"The baseline weekly growth without any sunlight is 2.7 centimeters."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable (weekly height growth) for each one-unit increase in the independent variable (hours of sunlight per day). A slope of 2.7 means the predicted weekly growth increases by 2.7 centimeters for each additional hour of daily sunlight. The claim about reaching maximum height at 2.7 hours confuses the slope with a specific threshold and misinterprets the linear model. The claim that growth is always 2.7 times the sunlight hours confuses the slope with direct proportionality, ignoring the y-intercept. The claim about a baseline of 2.7 centimeters confuses the slope with the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MAETC9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $MNP$ with the right angle at $P$, $\\tan(M) = \\frac{20}{21}$. If the hypotenuse $MN$ has length $87$, what is the length of the shorter leg?', NULL, $lyceon_json$[{"key":"A","text":"$20$"},{"key":"B","text":"$29$"},{"key":"C","text":"$60$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\tan(M) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{NP}{MP} = \\frac{20}{21}$, let $NP = 20k$ and $MP = 21k$. By the Pythagorean theorem, $MN = \\sqrt{(20k)^2 + (21k)^2} = \\sqrt{400k^2 + 441k^2} = \\sqrt{841k^2} = 29k$. Since $MN = 87$, we get $29k = 87$, so $k = 3$. The legs are $NP = 60$ and $MP = 63$, so the shorter leg is $60$. The value $20$ is the numerator of the tangent ratio before scaling, ignoring the hypotenuse constraint. The value $29$ is the base ratio hypotenuse before scaling ($\\sqrt{20^2 + 21^2} = 29$), reporting the unscaled hypotenuse rather than a leg. The value $63$ is the longer leg $MP = 21(3) = 63$, selecting the wrong leg when asked for the shorter one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OGTMWG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A florist can spend at most $\\$527$ on supplies for an event. Each centerpiece arrangement requires $\\$31$ in flowers, and there is a one-time delivery fee of $\\$93$. What is the maximum number of centerpiece arrangements the florist can prepare within this budget?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The inequality is $31c + 93 \\leq 527$. Subtracting 93 from both sides gives $31c \\leq 434$, and dividing by 31 gives $c \\leq 14.0$. Since the florist can only prepare a whole number of arrangements, the maximum is exactly 14. A common error is forgetting to subtract the delivery fee before dividing, which would give $527 / 31 = 17$ and a wrong answer of 17. Another error is setting up the inequality without the delivery fee and arriving at a different count.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OTAJO8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A square pyramid has a base with side length $11$ centimeters and a height of $15$ centimeters. What is the volume of the pyramid, in cubic centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '605', ARRAY['605'], E'The volume of a pyramid is $V = \\frac{1}{3}Bh$, where $B$ is the area of the base. The base is a square with side $11$ cm, so $B = 11^2 = 121$ square centimeters. Therefore $V = \\frac{1}{3}(121)(15) = \\frac{1815}{3} = 605$ cubic centimeters.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P525KL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant $k$ does the system of equations below have infinitely many solutions?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P8TWAR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new soil additive increases tomato yield. They randomly select $66$ farms in a temperate river valley and randomly assign $33$ farms to use the new additive while $33$ farms use their existing soil treatment. After one growing season, farms using the new additive produce significantly higher tomato yields on average. A fertilizer company''s advertisement states: "New soil additive guarantees increased tomato yields in every climate and soil type." Which of the following best evaluates the advertisement''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the study used random assignment of farms to treatment groups."},{"key":"B","text":"The claim is supported because the yield difference was statistically significant."},{"key":"C","text":"The claim overgeneralizes because all farms were in a temperate river valley, so the results may not apply to different climates, soil types, or growing conditions."},{"key":"D","text":"The claim is invalid because the researchers should have asked farmers which additive they preferred before assigning treatments."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within this study, all farms were located in a single temperate river valley. Soil composition, rainfall patterns, temperature ranges, and pest pressures vary greatly across regions, so the results cannot be generalized to every climate and soil type. Additionally, the advertisement claims the additive "guarantees" increased yields, which overstates even a statistically significant finding. Citing random assignment alone or statistical significance alone as justification ignores the limitation on generalizability — both support internal validity but do not address external validity. Suggesting that farmers should have chosen their own additive reflects a misunderstanding of experimental design: allowing self-selection would introduce confounding variables and undermine the study''s ability to establish causation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P93FQI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $19$ units. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$19\\pi$"},{"key":"B","text":"$38\\pi$"},{"key":"C","text":"$361\\pi$"},{"key":"D","text":"$1444\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(19)^2 = 361\\pi$. The value $19\\pi$ uses the circumference-like formula $\\pi r$ instead of $\\pi r^2$, a concept gap about the area formula. The value $38\\pi$ computes the circumference $2\\pi r = 2\\pi(19) = 38\\pi$ instead of the area, confusing the two formulas. The value $1444\\pi$ squares the diameter instead of the radius: $\\pi(38)^2 = 1444\\pi$, an error in identifying which measurement to square.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PAPAGZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A storage tank initially holds $3{,}150$ liters of oil. A pump removes oil at a constant rate of $45$ liters per minute. After how many minutes will the tank contain exactly $630$ liters?', NULL, $lyceon_json$[{"key":"A","text":"$56$"},{"key":"B","text":"$14$"},{"key":"C","text":"$70$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of oil after $t$ minutes is $V(t) = 3{,}150 - 45t$. Setting $V(t) = 630$: $3{,}150 - 45t = 630$. Subtracting $3{,}150$ from both sides gives $-45t = -2{,}520$, so $t = 56$. The value $14$ arises from misreading the question and dividing $630$ by $45$ directly, as if $630$ were the amount removed rather than the amount remaining. The value $70$ comes from an equation setup error: dividing $3{,}150$ by $45$, which gives the time to drain the entire tank rather than the time to reach $630$ liters. The value $84$ results from partial reasoning, incorrectly adding the two intermediate quotients $70$ and $14$ together.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PHYIK6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = -7x^4 + 3x^3 - x + 19$. Which of the following correctly describes the end behavior of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $p(x) \\to \\infty$; as $x \\to -\\infty$, $p(x) \\to -\\infty$"},{"key":"B","text":"As $x \\to \\infty$, $p(x) \\to -\\infty$; as $x \\to -\\infty$, $p(x) \\to \\infty$"},{"key":"C","text":"As $x \\to \\infty$, $p(x) \\to -\\infty$; as $x \\to -\\infty$, $p(x) \\to -\\infty$"},{"key":"D","text":"As $x \\to \\infty$, $p(x) \\to 19$; as $x \\to -\\infty$, $p(x) \\to 19$"}]$lyceon_json$::jsonb, 'C', NULL, E'The leading term of $p(x) = -7x^4 + 3x^3 - x + 19$ is $-7x^4$. For an even-degree polynomial with a negative leading coefficient, both ends go to $-\\infty$: as $x \\to \\infty$, $p(x) \\to -\\infty$, and as $x \\to -\\infty$, $p(x) \\to -\\infty$. The distractor stating opposite directions (up-right, down-left) describes odd-degree positive-leading-coefficient behavior, confusing even-degree and odd-degree end behavior. The distractor stating $p(x) \\to -\\infty$ as $x \\to \\infty$ but $p(x) \\to \\infty$ as $x \\to -\\infty$ describes odd-degree negative-leading-coefficient behavior, applying the wrong parity. The distractor claiming both ends approach $19$ treats the constant term as a horizontal asymptote, which does not apply to polynomial functions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PZN9AB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A shelf holds $13$ mystery novels, $8$ science fiction novels, and $6$ poetry collections. If one book is selected at random from the shelf, what is the probability that the book is a science fiction novel?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{27}$"},{"key":"B","text":"$\\frac{8}{19}$"},{"key":"C","text":"$\\frac{13}{27}$"},{"key":"D","text":"$\\frac{6}{27}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of books is $13 + 8 + 6 = 27$. The probability of selecting a science fiction novel is $\\frac{8}{27}$. The distractor $\\frac{8}{19}$ divides the science fiction count by the number of non-science-fiction books ($13 + 6 = 19$) rather than the total, incorrectly setting up the denominator. The distractor $\\frac{13}{27}$ uses the count of mystery novels instead of science fiction novels. The distractor $\\frac{6}{27}$ uses the count of poetry collections instead of science fiction novels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QHVJT6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A line of best fit for a data set is given by $y = 3.9x + 17$. Using this model, what is the predicted value of $y$ when $x = 8$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48.2', ARRAY['241/5', '48.2'], E'Substituting $x = 8$: $y = 3.9(8) + 17 = 31.2 + 17 = 48.2$. A common error is computing $3.9 \\times 8$ as $32.2$ by adding $3.9 + 8$ instead of multiplying, giving $32.2 + 17 = 49.2$. Another error is forgetting the y-intercept entirely and reporting only $3.9 \\times 8 = 31.2$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RCM7IN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7(3x - 4) + 11x$?', NULL, $lyceon_json$[{"key":"A","text":"$32x - 28$"},{"key":"B","text":"$32x - 4$"},{"key":"C","text":"$10x - 28$"},{"key":"D","text":"$32x + 28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $7$ gives $7(3x - 4) + 11x = 21x - 28 + 11x = 32x - 28$. The distractor $32x - 4$ correctly combines $21x + 11x = 32x$ but fails to distribute the $7$ to $-4$, leaving the constant as $-4$ instead of $-28$. The distractor $10x - 28$ correctly computes $-28$ but fails to multiply $7 \\times 3x$, instead treating the coefficient as $3$ rather than $21$ before adding $11x$. The distractor $32x + 28$ correctly finds $32x$ but applies a sign error to the constant, writing $+28$ instead of $-28$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2REH7SL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $7, 11, 19, 19, 31, 43$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$19$"},{"key":"C","text":"$21.67$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has 6 values in order: $7, 11, 19, 19, 31, 43$. The median of an even-count data set is the average of the 3rd and 4th values: $\\frac{19 + 19}{2} = 19$. The value 15 comes from averaging the 2nd and 3rd values ($\\frac{11 + 19}{2} = 15$), using incorrect positions for the middle pair. The value 21.67 comes from computing the mean ($\\frac{7 + 11 + 19 + 19 + 31 + 43}{6} \\approx 21.67$) instead of the median. The value 25 comes from averaging the 4th and 5th values ($\\frac{19 + 31}{2} = 25$), misidentifying which two values are in the middle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJRSH2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces 47 pages every 2 minutes. At this rate, how many pages does the printer produce in 14 minutes?', NULL, $lyceon_json$[{"key":"A","text":"282"},{"key":"B","text":"329"},{"key":"C","text":"336"},{"key":"D","text":"658"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{47}{2} = 23.5$ pages per minute. In 14 minutes the printer produces $23.5 \\times 14 = 329$ pages. The value 282 results from an arithmetic slip such as computing $23.5 \\times 12 = 282$, using 12 minutes instead of 14. The value 336 comes from incorrectly rounding the rate up to 24 pages per minute before multiplying by 14. The value 658 arises from multiplying $47 \\times 14 = 658$, failing to divide by 2 to account for the 2-minute interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RK9H61', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $g$ is defined by $g(x) = -11x + 143$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Setting $g(x) = 0$ gives $-11x + 143 = 0$. Subtracting $143$ from both sides yields $-11x = -143$. Dividing both sides by $-11$ gives $x = 13$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SYUW0F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A concrete mix requires cement and sand in a ratio of $11:4$ by weight. If a contractor has 253 grams of cement, how many grams of sand are needed to maintain this ratio?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '92', ARRAY['92'], E'Using the ratio $\\frac{11}{4} = \\frac{253}{s}$, cross-multiplying gives $11s = 253 \\times 4 = 1012$, so $s = \\frac{1012}{11} = 92$ grams. A common error is dividing 253 by 4 to get 63.25, confusing which quantity corresponds to which part of the ratio. Another error is computing $253 \\times \\frac{11}{4} = 695.75$, multiplying by the ratio instead of its reciprocal.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T18KTA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{16x^2 - 49}{4x + 7}$ for $x \\neq -\\frac{7}{4}$?', NULL, $lyceon_json$[{"key":"A","text":"$4x + 7$"},{"key":"B","text":"$4x - 7$"},{"key":"C","text":"$16x - 49$"},{"key":"D","text":"$4x^2 - 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $16x^2 - 49$ is a difference of squares: $(4x)^2 - 7^2 = (4x + 7)(4x - 7)$. Dividing by $(4x + 7)$ cancels one factor, leaving $4x - 7$. The distractor $4x + 7$ results from a sign error — canceling the wrong factor and keeping the one that was divided out. The distractor $16x - 49$ comes from dividing each term of the numerator by $4x + 7$ separately rather than factoring, treating the fraction as if division distributes across a difference of squares. The distractor $4x^2 - 7$ reflects a conceptual gap in applying the difference-of-squares identity, incorrectly taking the square root of each term individually.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TVRH7D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $310$ residents in a large city found that $43\\%$ prefer bike lanes over additional parking, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $43\\%$ of all residents in the city prefer bike lanes over additional parking."},{"key":"B","text":"It is plausible that between $39\\%$ and $47\\%$ of all residents in the city prefer bike lanes over additional parking."},{"key":"C","text":"Between $39\\%$ and $47\\%$ of the sampled residents prefer bike lanes over additional parking."},{"key":"D","text":"No more than $47\\%$ of all residents in the city prefer bike lanes over additional parking."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error creates a confidence interval around the sample statistic: $43\\% \\pm 4\\%$, or $39\\%$ to $47\\%$. This means it is plausible that the true population proportion falls within this range. The claim that exactly $43\\%$ of all residents prefer bike lanes treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the sampled residents misapplies the interval — the margin of error addresses the population parameter, not the sample result, which is already known precisely. The claim of no more than $47\\%$ captures only the upper bound and ignores that the interval is two-sided, failing to convey the lower-bound constraint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VATY7Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $28$ and the hypotenuse has length $53$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$35$"},{"key":"C","text":"$45$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, $a^2 + b^2 = c^2$, where $a = 28$ and $c = 53$: $28^2 + b^2 = 53^2$, so $784 + b^2 = 2809$, giving $b^2 = 2025$ and $b = 45$. The value $25$ comes from subtracting the leg from the hypotenuse ($53 - 28 = 25$) instead of applying the Pythagorean theorem. The value $35$ results from an arithmetic slip, such as miscalculating $\\sqrt{2025}$ or making an error during the subtraction step. The value $81$ comes from adding the given values ($53 + 28 = 81$) rather than using the correct formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VB28T2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A hiker walks the first 56 kilometers at an average speed of 14 kilometers per hour and the remaining 63 kilometers at an average speed of 21 kilometers per hour. What is the hiker''s average speed, in kilometers per hour, for the entire trip?', NULL, $lyceon_json$[{"key":"A","text":"$15.5$"},{"key":"B","text":"$17$"},{"key":"C","text":"$17.5$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'Time for the first segment: $\\frac{56}{14} = 4$ hours. Time for the second segment: $\\frac{63}{21} = 3$ hours. Total distance: $56 + 63 = 119$ km. Total time: $4 + 3 = 7$ hours. Average speed: $\\frac{119}{7} = 17$ km/h. The value 15.5 results from an arithmetic slip such as miscalculating the total distance or one of the segment times. The value 17.5 comes from the conceptual error of simply averaging the two speeds as $\\frac{14 + 21}{2} = 17.5$, which ignores the different times spent at each speed. The value 19 results from weighting the speeds by distance rather than by time, overvaluing the faster segment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VBLWPI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the sum of the solutions to the equation $x^2 - 11x + 18 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$11$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-18$"}]$lyceon_json$::jsonb, 'B', NULL, E'By Vieta''s formulas, the sum of the roots of $x^2 + bx + c = 0$ equals $-b$. Here $b = -11$, so the sum is $-(-11) = 11$. This can be verified by factoring: $x^2 - 11x + 18 = (x - 9)(x - 2) = 0$, giving $x = 9$ or $x = 2$, and $9 + 2 = 11$. The distractor $-11$ takes the coefficient of $x$ directly without negating it. The distractor $18$ confuses the sum of the roots with the product of the roots (which equals the constant term). The distractor $-18$ negates the constant term, confusing the product formula with the sum formula and adding a sign error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VTSWUR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ is perpendicular to the line $3x - 4y = 12$ and passes through the point $(3, -1)$. What is the $y$-intercept of line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 3)$"},{"key":"B","text":"$(0, 5)$"},{"key":"C","text":"$(0, -3)$"},{"key":"D","text":"$(0, -5)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rearranging $3x - 4y = 12$ gives $y = \\frac{3}{4}x - 3$, so the slope is $\\frac{3}{4}$. A perpendicular line has slope $-\\frac{4}{3}$. Using point-slope form with $(3, -1)$: $y + 1 = -\\frac{4}{3}(x - 3)$, which gives $y + 1 = -\\frac{4}{3}x + 4$, so $y = -\\frac{4}{3}x + 3$. The $y$-intercept is $(0, 3)$. The intercept $(0, 5)$ results from a sign error: using the point as $(3, 1)$ instead of $(3, -1)$, leading to $y - 1 = -\\frac{4}{3}(x - 3)$ and $y = -\\frac{4}{3}x + 5$. The intercept $(0, -3)$ reflects a concept gap, simply using the $y$-intercept of the original line without accounting for the new point or the perpendicular slope. The intercept $(0, -5)$ comes from an equation setup error: using the reciprocal slope $\\frac{4}{3}$ instead of the negative reciprocal $-\\frac{4}{3}$, giving $y + 1 = \\frac{4}{3}(x - 3)$, then $y = \\frac{4}{3}x - 5$, so $b = -5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WFPPY2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system $y = 3x^2 - 10x + k$ and $y = 2x - 7$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $3x^2 - 10x + k = 2x - 7$, which simplifies to $3x^2 - 12x + (k + 7) = 0$. For exactly one real solution, the discriminant must equal zero: $(-12)^2 - 4(3)(k + 7) = 0$. This gives $144 - 12(k + 7) = 0$, so $144 - 12k - 84 = 0$, thus $60 = 12k$ and $k = 5$. The distractor $-5$ results from a sign error when solving for $k$, negating the final answer. The distractor $7$ comes from using only the constant from the linear equation rather than completing the full discriminant calculation. The distractor $12$ arises from computing $\\frac{144}{12} = 12$ without accounting for the $-84$ term from distributing $-12 \\times 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WS441R', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{2x + 9}{5} - \\frac{x - 3}{4} = 3\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$13$"},{"key":"C","text":"$-16$"},{"key":"D","text":"$\\frac{1}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying every term by $20$ (the LCD of $5$ and $4$) gives $4(2x + 9) - 5(x - 3) = 60$. Expanding: $8x + 36 - 5x + 15 = 60$, so $3x + 51 = 60$. Subtracting $51$ yields $3x = 9$, thus $x = 3$. The value $13$ results from a sign error when distributing $-5(x - 3)$: writing $-5x - 15$ instead of $-5x + 15$ produces $3x + 21 = 60$, giving $3x = 39$ and $x = 13$. The value $-16$ arises from partial reasoning: failing to multiply the right-hand side by the LCD, solving $3x + 51 = 3$ instead of $60$, which gives $3x = -48$ and $x = -16$. The value $\\frac{1}{2}$ comes from an arithmetic slip: incorrectly applying the LCD multipliers as $5$ and $4$ rather than $4$ and $5$, leading to $10x + 45 - 4x + 12 = 60$, then $6x + 57 = 60$, $6x = 3$, and $x = \\frac{1}{2}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X30B1J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the daily temperature (in degrees Celsius) and the number of visitors to a park for 35 days. The line of best fit is $v = 2.3t - 7$, where $v$ is the predicted number of visitors in hundreds and $t$ is the temperature in degrees Celsius. On a day when the temperature is 9 degrees Celsius, the actual number of visitors is 1,500. What is the residual for this observation, in hundreds of visitors?', NULL, $lyceon_json$[{"key":"A","text":"$-1.3$"},{"key":"B","text":"$1.3$"},{"key":"C","text":"$13.7$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted number of visitors at $t = 9$ is $v = 2.3(9) - 7 = 20.7 - 7 = 13.7$ (in hundreds). The actual number is 1,500, which is 15 (in hundreds). The residual is the actual value minus the predicted value: $15 - 13.7 = 1.3$. The value $-1.3$ results from reversing the subtraction order, computing predicted minus actual instead of actual minus predicted. The value 13.7 is the predicted value itself, not the residual. The value 15 is the actual observed value converted to hundreds, not the difference between actual and predicted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y9DLPM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $WXY$ with the right angle at $Y$, $\\sin(W) = \\frac{11}{61}$. What is $\\cos(W)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60/61', ARRAY['60/61', '0.983', '.983', '0.984', '.984'], E'Since $\\sin(W) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{61}$, the side opposite angle $W$ (which is $XY$) has length $11$ and the hypotenuse $WX$ has length $61$. By the Pythagorean theorem, the adjacent side $WY = \\sqrt{61^2 - 11^2} = \\sqrt{3721 - 121} = \\sqrt{3600} = 60$. Therefore $\\cos(W) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{60}{61}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW203C5WC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation, if accurate, would most directly support the researchers'' claim about the vine''s growth pattern?', E'Botanists at the University of the West Indies have documented an unusual growth pattern in the tropical vine Marcgravia evenia. Unlike most climbing plants, which grow toward the nearest source of light, M. evenia sends out lateral shoots that consistently grow away from light and toward the darkest available surface. The researchers claim that this negative phototropism allows the vine to locate and attach to tree trunks more reliably than positive phototropism would, because in a dense tropical forest canopy, the darkest nearby surfaces are almost invariably the trunks of large trees.', $lyceon_json$[{"key":"A","text":"\"When we experimentally illuminated tree trunks from multiple angles, M. evenia shoots redirected within 48 hours to grow toward the nearest unilluminated trunk surface, confirming their consistent orientation away from light and toward solid vertical structures.\""},{"key":"B","text":"\"M. evenia produces unusually large leaves compared to other climbing vines in the same habitat, which may help it capture more sunlight once it reaches the canopy.\""},{"key":"C","text":"\"The root system of M. evenia extends up to 3.7 meters from the base of the plant, allowing it to access water from a wider area than most tropical vines.\""},{"key":"D","text":"\"Seventeen species of climbing plants in the same forest were observed growing toward light sources, following the typical positive phototropic pattern.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' claim is that M. evenia''s negative phototropism — growing away from light — helps it locate tree trunks reliably. The quotation describing shoots redirecting toward unilluminated trunk surfaces when trunks were experimentally lit from multiple angles directly demonstrates this light-avoidance behavior and its connection to finding solid structures. The quotation about large leaves describes a morphological trait unrelated to the vine''s directional growth pattern. The quotation about root extent addresses water access, not phototropic behavior. The quotation about other species growing toward light describes the behavior of different plants and, while providing contrast, does not directly support the specific claim about M. evenia''s growth pattern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20RHRH3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A research group at the University of Tromsø published findings in 2024 showing that Arctic cod (Boreogadus saida) in the Barents Sea have developed a previously undocumented feeding behavior during the polar night. Using acoustic tags attached to 114 individual fish across seven fjords, the researchers tracked the cod descending to depths of 370 to 410 meters during the darkest months of December and January to feed on bioluminescent copepods — tiny crustaceans that emit faint blue light. The cod appeared to use this bioluminescence as a hunting cue, orienting toward light flashes in otherwise total darkness, which allowed them to maintain caloric intake during a period when most Arctic fish species reduce feeding activity by as much as 80%.', $lyceon_json$[{"key":"A","text":"Arctic cod in the Barents Sea exploit bioluminescent prey at great depths during the polar night, enabling them to sustain feeding when most other Arctic fish species significantly reduce their food intake."},{"key":"B","text":"Bioluminescent copepods are the primary food source for all Arctic fish species during the winter months."},{"key":"C","text":"The University of Tromsø was the first institution to use acoustic tagging technology on Arctic marine organisms."},{"key":"D","text":"Arctic cod migrate to shallow waters during December and January to take advantage of increased plankton blooms near the surface."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic cod dive to depths of 370 to 410 meters during the polar night to feed on bioluminescent copepods, using light flashes as hunting cues when other Arctic fish reduce feeding activity. The option about exploiting bioluminescent prey to sustain feeding captures this central idea. The option claiming copepods are the primary food source for all Arctic fish overgeneralizes — the passage discusses only Arctic cod''s behavior, not all Arctic species. The option about being the first to use acoustic tagging introduces a claim the passage never makes. The option about migrating to shallow waters directly contradicts the passage, which specifies that the cod descend to great depths, not rise to the surface.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20UEH2A', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeobotanist Lena Sundqvist has proposed that the sudden appearance of cultivated emmer wheat in southern Scandinavia around 3900 BCE was not the result of gradual adoption by local foraging communities but rather of a rapid migration of farming populations from central Europe. She cites the absence of intermediate-phase archaeological sites -- locations showing mixed foraging and farming practices -- as evidence that the transition was too abrupt to have been a slow, indigenous process. Other scholars have pointed out, however, that preservation conditions in Scandinavian peat soils heavily favor organic farming debris over the lighter residues of foraging activity, which decay more quickly. _______ what Sundqvist interprets as an absence of transitional sites may instead reflect a systematic preservation bias that causes foraging evidence to disappear from the archaeological record while farming evidence persists.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Notwithstanding this,"},{"key":"C","text":"In addition,"},{"key":"D","text":"As a consequence,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank explains that Scandinavian peat soils preserve farming debris better than foraging residues. The sentence after the blank restates this observation as a direct implication for Sundqvist''s argument: her claimed absence of transitional sites may simply reflect differential preservation rather than a genuine historical absence. "In other words," correctly signals that the subsequent sentence is rephrasing the preceding observation in terms of its consequence for the debate. "Notwithstanding this," implies the subsequent sentence proceeds despite the preservation-bias observation, but the sentence after the blank builds directly on that observation rather than setting it aside. "In addition," would introduce a separate, supplementary point, but the subsequent sentence restates and draws out the implication of the same preservation issue already mentioned. "As a consequence," might seem plausible since the sentence describes an implication, but the sentence after the blank is not describing a causal effect of the preservation bias -- it is reinterpreting Sundqvist''s evidence in light of that bias, which is a reformulation rather than a downstream consequence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
