INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW244CFE9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Documentary filmmaker Yusuf Kerimoğlu spent three years recording oral histories from displaced communities in _____ his footage captures not only the personal narratives of migration but also the gradual erosion of linguistic traditions that had persisted for centuries.', $lyceon_json$[{"key":"A","text":"Diyarbakır, Turkey;"},{"key":"B","text":"Diyarbakır Turkey;"},{"key":"C","text":"Diyarbakır, Turkey,"},{"key":"D","text":"Diyarbakır Turkey,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two conventions operate simultaneously. First, the city-country pair "Diyarbakır, Turkey" requires a comma between the geographic components. Second, two independent clauses flank the blank, so a semicolon is needed to join them correctly. The combination "Diyarbakır, Turkey;" satisfies both requirements. Omitting the comma between the geographic names ("Diyarbakır Turkey;") violates the convention for punctuating geographic pairs, even though the semicolon correctly handles the clause boundary. Using a comma after "Turkey" instead of a semicolon ("Diyarbakır, Turkey,") properly punctuates the geographic pair but creates a comma splice between the two independent clauses. Omitting the internal geographic comma and using only a trailing comma ("Diyarbakır Turkey,") fails on both counts: no separator between the geographic names and a comma splice between independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
