INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27HYI66', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Geochemist Tomáš Dvořák has questioned a widely held assumption in planetary science: that the ratio of heavy to light xenon isotopes in Earth''s atmosphere can be explained entirely by the gravitational escape of lighter isotopes over billions of years. Previous models suggested that Earth''s early atmosphere lost light xenon preferentially because these atoms, being less massive, reached escape velocity more easily, leaving the atmosphere enriched in heavier isotopes relative to the solar composition. Dvořák''s laboratory simulations, however, showed that when xenon interacts with hydrogen-rich plasma conditions resembling those of Earth''s Hadean atmosphere, a mass-independent fractionation process occurs: xenon atoms of all masses are ionized at different rates depending on their nuclear spin configurations rather than their mass, producing isotope ratios that closely match Earth''s modern atmospheric signature. If Dvořák''s mechanism is primary, it would mean that Earth''s xenon anomaly reflects ancient atmospheric chemistry rather than 4.5 billion years of selective gravitational loss, significantly shortening the timescale over which the anomaly could have developed.', $lyceon_json$[{"key":"A","text":"Dvořák proposes that Earth's xenon isotope ratio results from a chemistry-driven process in the early atmosphere rather than from billions of years of mass-dependent gravitational escape, which would alter the understood timescale of the anomaly's formation."},{"key":"B","text":"Earth's atmosphere has lost nearly all of its original xenon through gravitational escape, leaving only trace amounts that are difficult to measure accurately."},{"key":"C","text":"Dvořák has proven that hydrogen-rich plasma conditions existed continuously in Earth's atmosphere from the Hadean eon through the present day."},{"key":"D","text":"The ratio of heavy to light xenon isotopes in Earth's atmosphere is identical to the solar composition, contradicting earlier measurements that suggested an enrichment in heavier isotopes."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Dvořák''s challenge to the gravitational escape model: he demonstrates a mass-independent fractionation mechanism driven by nuclear spin configurations in hydrogen-rich plasma, which could explain Earth''s xenon isotope ratios through atmospheric chemistry rather than prolonged gravitational loss. The option about chemistry-driven fractionation altering the timescale captures this main idea. The option about losing nearly all xenon fabricates a claim not present in the passage — the text discusses isotope ratios, not total xenon depletion. The option about proving continuous hydrogen-rich plasma overstates the research; Dvořák simulated Hadean conditions in a laboratory but did not claim those conditions persisted to the present. The option about Earth''s xenon matching solar composition directly contradicts the passage, which states that Earth''s atmosphere is enriched in heavier isotopes relative to solar composition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27JYUOY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Textile conservator Miriam Engström has been studying a collection of 53 medieval tapestries housed at the Nordiska Museet in Stockholm. Her analysis of thread composition revealed that 41 of the tapestries contain wool dyed with weld, a plant-based yellow pigment that was widely available in northern Europe during the fourteenth century. _______ the remaining 12 tapestries contain threads dyed with saffron, a far more expensive pigment imported from Mediterranean trade routes, which Engström interprets as evidence that these pieces were commissioned by wealthier patrons than those who ordered the weld-dyed works.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"For instance,"},{"key":"C","text":"As a result,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank describes the majority of tapestries (41 of 53) as containing an inexpensive, locally available pigment. The sentence after the blank describes a distinct minority (12 tapestries) that used a costly imported pigment, drawing a clear distinction in both material and implied patronage. "By contrast," correctly signals that the second group differs meaningfully from the first. "For instance," would introduce a specific example of the preceding claim, but the saffron-dyed tapestries are not an instance of weld-dyed tapestries -- they represent a separate category. "As a result," implies the saffron-dyed tapestries exist because of the weld-dyed ones, but no causal relationship between the two groups is described. "Granted," concedes a point that might weaken the speaker''s argument, but no argument is being qualified -- the passage is presenting two groups with different characteristics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27LYSHO', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economist Marguerite Delacroix studied pricing records from 39 independent cheese shops across rural France between 2018 and 2023. She found that shops located in villages with a weekly outdoor market consistently priced their cheeses 11% to 14% lower than shops in villages without a market, even when the shops themselves did not operate stalls at the market. Delacroix noted that outdoor markets in these villages typically included at least two vendors selling locally produced cheese at prices below those of permanent shops. This pattern suggests that ________', $lyceon_json$[{"key":"A","text":"the presence of market-day cheese vendors created competitive pressure that compelled permanent shops to lower their prices, regardless of whether the shops directly participated in the market."},{"key":"B","text":"cheese shops in villages without markets sold lower-quality products, which explains why their prices were higher."},{"key":"C","text":"customers in villages with outdoor markets purchased less cheese overall because the market vendors satisfied most of the local demand."},{"key":"D","text":"the outdoor markets were established specifically because permanent cheese shops in those villages were overcharging their customers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that permanent cheese shops priced lower in villages where outdoor markets included cheese vendors selling below shop prices. The logical completion is that market vendors created competitive pressure on permanent shops, forcing prices down even when the shops did not participate in the market directly. The option about lower-quality products introduces a quality difference the passage does not mention — the comparison is between shops in different village types, not between product quality levels. The option about reduced total cheese purchases introduces a demand-reduction claim unsupported by the text, which discusses pricing, not volume. The option about markets being created in response to overcharging reverses the causal relationship implied by the passage, which presents markets as influencing shop prices rather than shop prices motivating the creation of markets.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AT2GNM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Textile historian Amara Okonkwo spent seven years documenting the weaving techniques of artisans in northern Ghana _____ the resulting archive contains detailed recordings of over forty distinct patterns once thought to have been lost during the colonial period.', $lyceon_json$[{"key":"A","text":"Ghana, the"},{"key":"B","text":"Ghana. The"},{"key":"C","text":"Ghana the"},{"key":"D","text":"Ghana and, the"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses flank the blank: one about Okonkwo''s documentation work and another about the archive''s contents. A period correctly separates these into two complete sentences. Using only a comma ("Ghana, the") creates a comma splice by joining two independent clauses without a coordinating conjunction. Omitting all punctuation ("Ghana the") produces a fused sentence. Inserting "and" with a misplaced comma before "the" ("Ghana and, the") improperly interrupts the second clause with punctuation that serves no grammatical function.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ATNQ93', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "purchase" most nearly means', E'Literary critic Emeka Achebe contends that postcolonial readings of Joseph Conrad''s novels gained purchase in Anglophone academic departments during the 1980s partly because they offered a framework for reexamining canonical texts without abandoning close reading — a methodological compromise that allowed traditionalist faculty to engage with the new scholarship on familiar procedural ground.', $lyceon_json$[{"key":"A","text":"acquisition"},{"key":"B","text":"traction"},{"key":"C","text":"transaction"},{"key":"D","text":"discount"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes postcolonial readings gaining influence and acceptance within academic departments, establishing themselves as a viable interpretive approach. "Traction" correctly captures this sense of an idea gaining a foothold and building momentum within an institutional setting. "Acquisition" means the act of buying or obtaining a possession, which is incoherent when describing an intellectual framework''s growing influence in scholarly discourse. "Transaction" means a business deal or exchange of goods, which has no logical application to an academic movement''s increasing acceptance among faculty. "Discount" means a reduction in price, which is entirely unrelated to the passage''s discussion of how a scholarly approach gained standing in university departments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D34REJ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a literature review and wants to highlight how two researchers reached similar conclusions through fundamentally different methodologies. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D7WPJK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about a scientific instrument and wants to explain what the instrument does and where it is located. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F341LC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the city council announced plans to demolish the historic waterfront warehouses, a coalition of preservation advocates _____ an emergency petition that ultimately persuaded the planning commission to designate the buildings as protected landmarks.', $lyceon_json$[{"key":"A","text":"files"},{"key":"B","text":"filing"},{"key":"C","text":"filed"},{"key":"D","text":"has filed"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a past-tense frame with "announced" and "persuaded," so the main clause verb must also be in the past tense. The plural subject "coalition" (referring to a group that acts collectively) takes a singular or plural verb, but the key constraint is tense: the simple past "filed" matches the established past-tense narrative. The third-person singular present "files" breaks tense consistency by shifting to the present. The present participle "filing" is not a finite verb and cannot serve as the main predicate of the clause, producing a sentence fragment. The present perfect "has filed" shifts to a present-relevance tense that is inconsistent with the past-tense frame established by the surrounding verbs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HZ8EDB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Volcanologist Signe Lindqvist has monitored sulfur dioxide emissions at seventeen active vents across Iceland''s Central Highlands _____ her measurements suggest that subsurface magma reservoirs beneath the Vatnajökull ice cap are replenishing faster than previously modeled.', $lyceon_json$[{"key":"A","text":"Highlands, her"},{"key":"B","text":"Highlands her"},{"key":"C","text":"Highlands; her"},{"key":"D","text":"Highlands, and; her"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses appear on either side of the blank: one about Lindqvist''s monitoring activities and another about what her measurements suggest. A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. A comma alone ("Highlands, her") produces a comma splice. Omitting all punctuation ("Highlands her") creates a fused sentence. Combining a comma, a coordinating conjunction, and a semicolon ("Highlands, and; her") is malformed: the conjunction would suffice to join the clauses after a comma, making the semicolon superfluous, and the semicolon improperly separates the conjunction from the second clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J34CT0', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The bombardier beetle (Brachinus crepitans) defends itself by ejecting a boiling chemical spray from its abdomen at temperatures exceeding 100 degrees Celsius. Despite producing this extremely hot liquid internally, the beetle suffers no damage to its own tissues. Entomologists have discovered that the beetle''s reaction chamber is lined with a layer of chitin nearly three times thicker than that found in comparable body cavities of related beetle species. This thickened lining suggests that ________', $lyceon_json$[{"key":"A","text":"the reinforced chitin layer acts as thermal insulation, protecting the beetle's internal organs from the heat generated by its own defensive spray."},{"key":"B","text":"bombardier beetles are unable to produce their chemical spray more than once per day due to the time required to regenerate the chitin lining."},{"key":"C","text":"the chitin in bombardier beetles is chemically identical to the chitin found in all other insect species."},{"key":"D","text":"the boiling spray is produced outside the beetle's body rather than within an internal chamber."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the beetle produces boiling liquid internally without tissue damage and that the reaction chamber has an unusually thick chitin lining. The logical inference is that this thickened chitin serves as thermal insulation, explaining how the beetle avoids self-injury. The option about spraying only once per day and needing to regenerate chitin introduces a limitation not implied by the passage. The option about chemical identity of chitin across species states a fact that, even if true, does not follow from the observation about thickness. The option about external spray production directly contradicts the passage, which specifies that the spray is produced in an internal reaction chamber.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KHLM0E', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "currency" most nearly means', E'Sociologist Dara Okonkwo observes that certain folk remedies, despite lacking clinical validation, retain remarkable currency among rural communities in southeastern Nigeria. Okonkwo attributes their enduring acceptance to the social authority of village herbalists, whose recommendations carry weight that formal public health messaging has struggled to match.', $lyceon_json$[{"key":"A","text":"coinage"},{"key":"B","text":"prevalence"},{"key":"C","text":"expense"},{"key":"D","text":"novelty"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes folk remedies that remain widely accepted and in active circulation among communities, and the second sentence reinforces this with the phrase "enduring acceptance." "Prevalence" correctly captures the sense of something being widespread and commonly in use. "Coinage" refers to metal money or the process of minting coins, which is incoherent when describing the status of folk remedies in a community. "Expense" means the cost of something, which has no connection to the passage''s discussion of how widely accepted the remedies are. "Novelty" means the quality of being new or unusual, which contradicts the passage''s emphasis on the remedies'' long-standing and enduring acceptance.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KMF1SP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Based on the text, what does Nakamura''s analysis primarily reveal about the manuscripts she studied?', E'Literary scholar Yuki Nakamura examined 67 handwritten draft manuscripts of short stories by the Meiji-era Japanese author Higuchi Ichiyō, comparing the frequency and type of revisions Ichiyō made across three distinct periods of her career: 1892–1893, 1894, and 1895–1896. Nakamura found that in the earliest manuscripts, Ichiyō primarily revised word-level vocabulary, replacing individual kanji compounds an average of 4.3 times per page. During the middle period, revisions shifted to sentence-level restructuring, with Ichiyō rearranging clause order and altering grammatical constructions while leaving her initial vocabulary choices largely intact. In the final period, revisions became paragraph-level: Ichiyō frequently reordered entire narrative sequences and deleted or relocated descriptive passages, but rarely changed individual words or sentence structures. Nakamura argues that this progression reflects Ichiyō''s increasing confidence in her linguistic choices and a growing preoccupation with narrative architecture over surface-level expression.', $lyceon_json$[{"key":"A","text":"Ichiyō's revision patterns shifted over her career from word-level changes to larger structural reorganizations, suggesting growing confidence in her language and increasing focus on narrative structure."},{"key":"B","text":"Ichiyō's writing quality declined in her final period because she stopped revising individual words and sentences."},{"key":"C","text":"The manuscripts from 1894 contain the fewest total revisions of any period, indicating that Ichiyō wrote most fluently during that year."},{"key":"D","text":"Nakamura's analysis demonstrates that Ichiyō borrowed vocabulary from contemporary Western authors during her earliest period but abandoned this practice after 1893."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how Ichiyō''s revisions evolved from word-level vocabulary substitutions to sentence-level restructuring to paragraph-level narrative reorganization, with Nakamura interpreting this as reflecting growing linguistic confidence and a shift toward narrative architecture. The option describing this progression accurately captures the primary finding. The option about declining quality misinterprets the shift — Nakamura frames the reduction in word-level revisions as confidence, not deterioration. The option about fewest total revisions in 1894 fabricates a claim the passage does not make; the passage describes a change in revision type, not total revision count. The option about borrowing Western vocabulary introduces a claim entirely absent from the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MQYF91', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the seventeen doctoral candidates who presented findings at the symposium _____ required to submit a revised manuscript incorporating the feedback received from the review panel before the proceedings could be finalized.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"are"},{"key":"C","text":"was"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the main clause is "each," a singular indefinite pronoun, not the plural noun "candidates" that appears in the intervening prepositional phrase. The past tense is established by "presented," "received," and "could be finalized." The singular past-tense "was" correctly agrees with "each" and maintains tense consistency. The plural past-tense "were" would agree with "candidates" but not with the actual subject "each." The plural present-tense "are" fails on both number agreement with the singular subject and tense consistency with the past-tense frame. The plural present-perfect "have been" also fails on number agreement and introduces a tense shift away from the established past narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OC5IU8', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'The leafy sea dragon, a marine fish native to the southern coast of Australia, possesses elaborate leaf-shaped appendages that extend from its body. These appendages are not used for swimming; instead, they serve exclusively as camouflage, allowing the fish to blend seamlessly with the kelp and seaweed beds it inhabits along rocky reefs.', $lyceon_json$[{"key":"A","text":"To describe a physical feature of an animal and explain its biological function"},{"key":"B","text":"To argue that the leafy sea dragon should be reclassified as a plant rather than a fish"},{"key":"C","text":"To compare the swimming techniques of several species of Australian marine fish"},{"key":"D","text":"To trace the evolutionary origins of camouflage in oceanic vertebrates"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the leafy sea dragon''s appendages and then clarifies their purpose — camouflage rather than locomotion. Its function is to identify a distinctive physical trait and explain what it does. Arguing for reclassification as a plant has no basis in the passage, which identifies the organism as a fish and describes its appendages as camouflage structures, not plant tissue. Comparing swimming techniques of multiple species mischaracterizes the passage, which discusses only one species and explicitly states the appendages are unrelated to swimming. Tracing the evolutionary origins of camouflage overstates the passage''s scope; it describes what the appendages do in the present, not how camouflage evolved over time across vertebrate lineages.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PL0801', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the passage ("Her team cataloged . . . by adjacent marshland")?', E'Hydrologist Renata Stavros challenged the prevailing model that seasonal flooding in the Danube Delta is driven primarily by snowmelt discharge from upstream tributaries. Her team cataloged flood-timing data from 23 hydrological stations across the delta over a nineteen-year span, finding that peak water levels at eleven interior stations preceded upstream discharge peaks by an average of seventeen days — a pattern more consistent with local precipitation and groundwater saturation than with a snowmelt-driven pulse propagating downstream. Stavros argues that interior flood dynamics are substantially governed by localized rainfall absorbed and slowly released by adjacent marshland.', $lyceon_json$[{"key":"A","text":"It presents the data and finding that undercut the model introduced in the first sentence"},{"key":"B","text":"It offers a concession that partially supports the prevailing snowmelt discharge model"},{"key":"C","text":"It describes the geographic boundaries of the Danube Delta region studied by Stavros"},{"key":"D","text":"It summarizes previous researchers' conclusions about upstream tributary behavior"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence establishes the prevailing model that Stavros challenges. The second sentence provides the empirical backbone of her challenge: data showing that interior flood peaks arrive before upstream discharge peaks, a timing inconsistency that undermines the snowmelt-driven explanation. Offering a concession to the prevailing model contradicts the sentence''s function; the seventeen-day discrepancy directly weakens, rather than partially supports, the snowmelt hypothesis. Describing the geographic boundaries of the study area misidentifies the sentence''s purpose; while it mentions hydrological stations, its core function is to report a temporal finding about flood timing, not to delineate a geographic region. Summarizing previous researchers'' conclusions is unsupported; the sentence presents Stavros''s own team''s data collection and analysis, not a review of prior scholarship on tributary behavior.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q3VQVE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'For decades, linguists assumed that pidgin languages — simplified contact languages arising when speakers of mutually unintelligible languages need to communicate — were inherently unstable and destined to either creolize into full languages or disappear within a generation. Linguist Fatiha Benali, working with fishing communities along the Mauritanian coast, documented a pidgin combining elements of Hassaniya Arabic and Wolof that has persisted in a stable, non-creolized form for at least ninety years across four generations of speakers. Benali attributes this stability to the specific socioeconomic conditions of the fishing trade, in which the pidgin fulfills a narrow but essential communicative function that neither full language can serve alone.', $lyceon_json$[{"key":"A","text":"It states a longstanding assumption, presents a case that defies the assumption, and proposes an explanation for the anomaly"},{"key":"B","text":"It defines a technical term, provides several historical examples of the phenomenon, and ranks them by significance"},{"key":"C","text":"It introduces Benali's research methodology, reports her statistical findings, and evaluates their limitations"},{"key":"D","text":"It contrasts two competing theories of language evolution and endorses one as more empirically supported"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a three-part structure: it presents the conventional assumption that pidgins are unstable and short-lived, introduces Benali''s documented counterexample of a pidgin that has persisted for ninety years, and then offers her explanation for why this pidgin has remained stable. Defining a term and providing ranked historical examples mischaracterizes the passage, which offers one specific case study rather than multiple examples, and does not rank anything by significance. Introducing research methodology, reporting statistics, and evaluating limitations does not match the passage, which focuses on a finding and its explanation rather than detailing how data was collected or acknowledging weaknesses. Contrasting two competing theories misidentifies the structure; the passage presents one prevailing assumption and one researcher''s contradictory finding, not two rival theoretical frameworks being weighed against each other.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QG9P2P', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "arrested" most nearly means', E'The conservator explained that the deterioration of the seventeenth-century oak panel had been arrested by a thin coat of microcrystalline wax applied sometime in the 1940s, which sealed the wood against further moisture absorption and insect damage.', $lyceon_json$[{"key":"A","text":"detained"},{"key":"B","text":"halted"},{"key":"C","text":"convicted"},{"key":"D","text":"accelerated"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes deterioration that was stopped by a protective wax coating, indicating the damage ceased progressing. "Halted" correctly captures this sense of a process being brought to a stop. "Detained" means to hold someone in custody or delay a person, which is incoherent when applied to a chemical process affecting wood. "Convicted" means to declare someone guilty of a criminal offense, which has no logical connection to the prevention of wood decay. "Accelerated" means to increase the speed of something, which directly contradicts the passage''s indication that the wax prevented further damage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QN09RN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team finished restoring the wetland habitat, the population of nesting shorebirds _____ steadily for three consecutive breeding seasons, a recovery that exceeded the projections outlined in the original management plan.', $lyceon_json$[{"key":"A","text":"has increased"},{"key":"B","text":"had been increasing"},{"key":"C","text":"was increasing"},{"key":"D","text":"increased"}]$lyceon_json$::jsonb, 'B', NULL, E'The construction "by the time the conservation team finished" establishes a past reference point, and the phrase "for three consecutive breeding seasons" indicates an action that was ongoing up to that point. The past perfect progressive "had been increasing" correctly expresses a continuous action that began before and extended up to a completed past event. The present perfect "has increased" improperly shifts the tense frame to the present, breaking consistency with the past-tense narrative established by "finished." The past progressive "was increasing" indicates an action in progress at a past moment but does not properly convey the anterior duration required by the "by the time... finished" construction, which calls for the past perfect to sequence one past event before another. The simple past "increased" fails to convey the ongoing, progressive nature of the recovery indicated by "steadily for three consecutive breeding seasons" and does not establish the necessary temporal sequencing before the past reference point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
