INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VK56QO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support Petrov''s hypothesis?', E'Glaciologist Dmitri Petrov analyzed sediment cores extracted from beneath the Vavilov Ice Cap on October Revolution Island in the Russian Arctic. He observed that a layer of volcanic ash dated to approximately 3,200 years ago was overlain by an unusually thick deposit of refrozen meltwater — nearly 1.4 meters, compared to the typical 5 to 15 centimeters found above other ash layers in the same core. Petrov hypothesized that the dark volcanic ash absorbed significantly more solar radiation than the surrounding white ice surface, creating a localized melt zone that produced an exceptional volume of liquid water. This water then percolated downward and refroze beneath the ice cap''s cold interior, forming the anomalously thick refrozen layer directly above the ash.', $lyceon_json$[{"key":"A","text":"In controlled laboratory tests, simulated ice surfaces covered with a thin layer of volcanic ash absorbed 73% of incoming shortwave radiation, compared to 14% for clean ice surfaces under identical illumination conditions."},{"key":"B","text":"The volcanic eruption that produced the ash layer 3,200 years ago is believed to have originated from a caldera on a nearby island approximately 190 kilometers to the southeast."},{"key":"C","text":"Other ice caps in the Russian Arctic that lack volcanic ash layers show uniformly thin refrozen meltwater deposits throughout their sediment profiles."},{"key":"D","text":"The Vavilov Ice Cap has been thinning at an accelerating rate since satellite monitoring began in 1979, losing an average of 0.9 meters of thickness per decade."}]$lyceon_json$::jsonb, 'A', NULL, E'Petrov''s hypothesis is that dark volcanic ash absorbed more solar radiation than clean ice, creating localized melting that produced the thick refrozen layer. The laboratory finding that ash-covered ice absorbs 73% of shortwave radiation versus 14% for clean ice directly confirms the mechanism Petrov proposes — a dramatic difference in absorption that would explain enhanced melting above the ash. The finding about the eruption''s geographic origin provides context about the ash source but does not address whether ash increases radiation absorption or melting. The finding about other ice caps lacking ash having thin meltwater deposits is suggestive but only shows correlation; it does not directly test the absorption mechanism Petrov describes. The finding about modern ice cap thinning describes a contemporary trend unrelated to the 3,200-year-old ash layer and the specific mechanism hypothesized.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WHWQ96', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Fatou Diagne has cataloged over 370 species of invertebrates living on artificial reef structures installed off the coast of Senegal in 2019. Her surveys found that sponge colonies established themselves on the structures within the first seven months. _______ several species of reef fish, including juvenile groupers, began using the sponge-covered surfaces as shelter within a year of the sponges'' arrival.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"In turn,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank describes sponge colonies establishing themselves on the structures, and the sentence after the blank describes reef fish subsequently using those sponge-covered surfaces as shelter. "In turn," correctly signals a sequential development in which one event leads to the next. "Nevertheless," implies the fish behavior occurred despite the sponge colonization, but the passage presents the fish arrival as a natural consequence of it, not as something surprising. "On the contrary," signals a direct contradiction of the preceding claim, but the fish sheltering in sponge-covered surfaces does not contradict the sponges'' establishment. "Specifically," would narrow the general claim about sponge colonies to a particular detail, but the fish behavior is a separate subsequent development, not a specific instance of sponge colonization.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X5MJPD', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Sunita Parekh excavated a cluster of 29 ceramic kilns at a site in Gujarat, India, dating to the third century BCE. Chemical analysis of residual glazes in the kilns revealed that 26 of the 29 kilns had been used to fire pottery with a distinctive cobalt-blue glaze, while the remaining three kilns showed traces of an iron-red glaze. Notably, the three iron-red kilns were structurally identical to the cobalt-blue ones and were interspersed among them rather than separated into a distinct area. However, the iron-red kilns contained fire-box ash deposits nearly four times as thick as those in the cobalt-blue kilns, suggesting that they were fired at higher temperatures for longer durations. Parekh argues that the difference in ash accumulation, combined with the spatial integration of the two kiln types, indicates that ________', $lyceon_json$[{"key":"A","text":"the iron-red and cobalt-blue kilns were operated by the same workshop, with the iron-red kilns requiring more intensive firing conditions dictated by the chemistry of the iron-based glaze rather than by a different production tradition."},{"key":"B","text":"the iron-red kilns were built centuries after the cobalt-blue kilns by a separate group of potters who reoccupied the site."},{"key":"C","text":"cobalt-blue glazed pottery was considered less valuable than iron-red pottery in third-century BCE Gujarat, which is why fewer kilns were dedicated to the red glaze."},{"key":"D","text":"the thicker ash deposits in the iron-red kilns resulted from the kilns being used as cooking fires after pottery production at the site ceased."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage notes that the iron-red kilns are structurally identical to and spatially integrated with the cobalt-blue kilns, but have much thicker ash deposits indicating longer, hotter firings. The logical inference is that a single workshop operated both kiln types, with the different firing requirements reflecting the chemistry of the iron-based glaze rather than a separate production tradition. The option about later construction by a different group contradicts the passage''s emphasis on structural identity and spatial integration, which suggest contemporaneous use by the same operators. The option about relative value inverts the numerical evidence without textual support — the passage does not discuss the relative value of the two pottery types, and having fewer kilns does not logically indicate higher value. The option about cooking fires introduces a post-production use that is inconsistent with the glaze residues found in the kilns, which indicate ceramic production, not food preparation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XXSS54', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts donated to the university by a retired diplomat _____ several previously unknown letters written by a prominent nineteenth-century abolitionist.', $lyceon_json$[{"key":"A","text":"contain"},{"key":"B","text":"contains"},{"key":"C","text":"are containing"},{"key":"D","text":"have contained"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "collection," a singular noun, so the verb must agree in the singular. The sentence describes a present fact about what the collection includes, calling for the simple present tense. The third-person singular present "contains" satisfies both requirements. The bare plural form "contain" fails to agree with the singular subject. The present progressive "are containing" uses a plural auxiliary, failing number agreement, and "contain" is a stative verb that resists the progressive form in standard usage. The present perfect "have contained" uses a plural auxiliary, again failing number agreement with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y1RUZD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The neural network that computational linguist Saoirse Byrne trained on a corpus of medieval Irish _____ can identify scribal hands with an accuracy rate that surpasses even expert paleographers working with the same manuscripts.', $lyceon_json$[{"key":"A","text":"texts—which includes over forty thousand digitized folios—"},{"key":"B","text":"texts, which includes over forty thousand digitized folios"},{"key":"C","text":"texts—which includes over forty thousand digitized folios,"},{"key":"D","text":"texts which includes over forty thousand digitized folios"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "which includes over forty thousand digitized folios" is a nonrestrictive relative clause providing additional information about the corpus. Because this clause is embedded mid-sentence — interrupting the object ("a corpus of medieval Irish texts") and the main clause''s predicate ("can identify") — it must be set off by paired punctuation on both sides. Em dashes on both sides correctly bracket the interrupting clause. Using a comma before the clause but omitting the closing punctuation ("texts, which includes over forty thousand digitized folios can") leaves the nonrestrictive clause unclosed, causing the parenthetical to merge into the predicate and obscuring the sentence''s grammatical structure. Using an em dash before the clause and a comma after it ("texts—which includes over forty thousand digitized folios, can") creates mismatched boundary markers, which is not standard. Omitting all setting-off punctuation ("texts which includes over forty thousand digitized folios can") fuses the nonrestrictive clause into the sentence without the necessary boundary markers, making the clause appear restrictive and producing a confusing run of words.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YQ26Y6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if accurate, would most directly weaken Abubakar and Chen''s interpretation?', E'In a 2024 study, musicologists Fatima Abubakar and Liang Chen analyzed the melodic structures of 213 surviving notated compositions from the Abbasid court in Baghdad, dating between the ninth and eleventh centuries. They found that 78% of these compositions used intervals smaller than a Western semitone — microtonal intervals that do not appear in medieval European music of the same period. Abubakar and Chen interpreted this prevalence as evidence that Abbasid court musicians developed microtonal systems independently of Greek musical theory, which also employed microtones. They argued that the specific microtonal intervals used in the Abbasid compositions do not correspond to any intervals described in surviving Greek treatises, suggesting an indigenous musical innovation rather than a borrowing from Hellenistic traditions that were otherwise influential in Abbasid intellectual culture.', $lyceon_json$[{"key":"A","text":"A recently discovered Greek treatise from the second century BCE describes a set of microtonal intervals that closely match the intervals found in 71% of the Abbasid compositions Abubakar and Chen analyzed."},{"key":"B","text":"Medieval European musicians were aware of Abbasid musical practices through trade contacts but chose not to adopt microtonal intervals in their own compositions."},{"key":"C","text":"The Abbasid court employed musicians from at least 14 different ethnic and linguistic backgrounds, reflecting the cosmopolitan nature of Baghdad during this period."},{"key":"D","text":"Modern Iraqi maqam music continues to employ microtonal intervals similar to those found in the Abbasid compositions, demonstrating a continuous regional musical tradition."}]$lyceon_json$::jsonb, 'A', NULL, E'Abubakar and Chen''s interpretation rests on the claim that Abbasid microtonal intervals do not correspond to any intervals in surviving Greek treatises, supporting independent development. A newly discovered Greek treatise describing intervals closely matching 71% of the Abbasid compositions would directly undermine this foundation — if Greek theory already documented those intervals, the case for indigenous innovation collapses. The finding about European awareness of Abbasid music addresses East-West cultural contact but does not challenge whether the Abbasid intervals derived from Greek theory. The finding about diverse court musicians suggests cosmopolitanism but does not establish a link to Greek musical theory specifically. The finding about continuity in modern Iraqi maqam music demonstrates regional tradition but does not address the question of whether the original intervals were independent of Greek influence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z4KVGF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Yael Navarro has argued that municipal broadband networks consistently deliver faster internet speeds at lower per-household costs than private providers in comparable markets. Her 2022 analysis of 19 U.S. cities with public broadband infrastructure showed average download speeds 34% higher and monthly bills 22% lower than those in demographically similar cities served exclusively by private carriers. Critics have countered that Navarro''s comparison overlooks the substantial initial public investment required to build the municipal networks, which private carriers fund through their own capital. _______ Navarro has acknowledged the validity of the capital-cost objection but maintains that her analysis accounts for it through amortized infrastructure costs spread over a 25-year service life, yielding a net per-household savings of $137 annually even after including the public investment.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Admittedly,"},{"key":"C","text":"In response,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank presents critics'' objection to Navarro''s analysis -- that it ignores the upfront public investment. The sentence after the blank presents Navarro''s direct reply to that objection, acknowledging the concern but explaining how her analysis already accounts for it. "In response," correctly signals that what follows is a direct reply to the preceding criticism. "Furthermore," implies the subsequent sentence adds a new, supporting point to the critics'' objection, but it is Navarro''s counterargument, not an extension of the critics'' claim. "Admittedly," would frame the subsequent sentence as a concession that weakens Navarro''s own position, but while she acknowledges the objection, she goes on to rebut it by showing her analysis already incorporates the capital costs -- making the sentence a defense, not a pure concession. "Meanwhile," suggests two events occurring simultaneously or in parallel, but the passage describes a sequential exchange of argument and counterargument, not concurrent developments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
